// Get the top-level JSON object from the input
const inputData = $input.first().json;

// 1. Get the base64 data string from the API response
//    This path is now correct based on your provided data
const base64DataUrl = inputData.choices[0].message.images[0].image_url.url;

// 2. Split the string to remove the "data:image/png;base64," prefix
//    The error from before ('includes') will be fixed
//    because base64DataUrl will now be a valid string.
const base64String = base64DataUrl.split(',')[1];

// 3. Get the passthrough data we saved in the "Submit" node
const topic = inputData.topic;
const name = inputData.name;
const variationNumber = inputData.variationNumber;

// 4. Return all the data needed for the next nodes
return [{
  json: {
    base64Data: base64String, // This is now a clean string
    topic: topic,
    name: name,
    variationNumber: variationNumber
  }
}];

const variations = $input.first().json.variations;
const topic = $input.first().json.topic;
const brandName = $input.first().json.brandName;
const clientName = $input.first().json.clientName;
const clientEmail = $input.first().json.clientEmail;

const items = [];
for (let i = 1; i <= variations; i++) {
  items.push({
    json: {
      topic: topic,
      brandName: brandName,
      clientName: clientName,
      clientEmail: clientEmail,
      variationNumber: i
    }
  });
}

return items;

// Get all the items from the 'Merge' node
const items = $input.all();

// Loop over each item
const links = items.map(item => {
  const jsonData = item.json;

  // 1. Get the variation number (now in the direct input)
  const variationNumber = jsonData.variationNumber;

  // 2. Get the shareable link (also in the direct input)
  const shareableLink = jsonData.webViewLink;

  // 3. Return the HTML button string
  return `<a href="${shareableLink}" class="logo-link-btn">Download Variation ${variationNumber} 🚀</a>`;
}).join('');

// Get the common data from the first item
const firstItemData = items[0].json;

// Return the final, complete object for your email
return [{
  json: {
    clientName: firstItemData.clientName,
    clientEmail: firstItemData.clientEmail,
    brandName: firstItemData.brandName,
    topic: firstItemData.topic,
    variations: items.length,
    logoLinks: links
  }
}];

